const calls = [];

const env = {
  allowRemoteModels: true,
  cacheDir: null,
  backends: { onnx: {} },
};

const ModelRegistry = {
  is_pipeline_cached: function isPipelineCached() {
    return Promise.resolve(true);
  },
};

function pipeline(task, model, options) {
  calls.push([task, model, options]);
  const encoder = function stubEncoder(texts) {
    const list = Array.isArray(texts) ? texts : [texts];
    const n = list.length;
    const data = new Float32Array(n * 3);
    for (let i = 0; i < n; i += 1) {
      const s = String(list[i] == null ? '' : list[i]);
      data[i * 3] = s.length;
      data[i * 3 + 1] = (s.match(/[aeiou]/gi) || []).length;
      data[i * 3 + 2] = s.split(/\s+/).length;
    }
    return Promise.resolve({ data: data, dims: [n, 3] });
  };
  return Promise.resolve(encoder);
}

module.exports = { env: env, ModelRegistry: ModelRegistry, pipeline: pipeline, calls: calls };
